var authGuard = (route, state2) => {
  const authService = inject2(AuthService);
  const router = inject2(Router);
  const platformId = inject2(PLATFORM_ID);
  if (!isPlatformBrowser(platformId)) {
    return true;
  }
  if (!authService.isLoggedIn()) {
    console.warn("Acceso denegado. Redirigiendo al login...");
    router.navigate(["/login"]);
    return false;
  }
  const isPatient = authService.isPatient();
  const targetUrl = state2.url;
  if (isPatient && targetUrl.startsWith("/dashboard")) {
    console.warn("Paciente intent\xF3 acceder al CRM. Redirigiendo a /mis-citas...");
    router.navigate(["/mis-citas"]);
    return false;
  }
  if (!isPatient && targetUrl.startsWith("/mis-citas")) {
    console.warn("Staff intent\xF3 acceder al portal de pacientes. Redirigiendo al dashboard...");
    router.navigate(["/dashboard"]);
    return false;
  }
  return true;
};

// src/app/core/guards/public.guard.ts
var publicGuard = () => {
  const authService = inject2(AuthService);
  const router = inject2(Router);
  if (authService.isLoggedIn()) {
    router.navigate([authService.getHomeRoute()]);
    return false;
  }
  return true;
};

// src/app/core/guards/role.guard.ts
var roleGuard = (route, state2) => {
  const auth = inject2(AuthService);
  const router = inject2(Router);
  const toastr = inject2(ToastrService);
  const allowedRoles = route.data["roles"];
  const user = auth.currentUser();
  if (!allowedRoles || allowedRoles.length === 0) {
    return true;
  }
  const role = user?.rol || user?.role;
  if (role && allowedRoles.includes(role)) {
    return true;
  }
  toastr.error("No tienes permisos suficientes para acceder a este m\xF3dulo.", "Acceso Denegado");
  router.navigate([auth.getHomeRoute()]);
  return false;
};

